#include "vulkan/VulkanNeuralExecutionPlan.h"
#include <cassert>
#include <iostream>
int main(int argc,char**argv){using namespace bncam::vulkan::neural;if(argc<2)return 2;auto m=loadNeuralModelPackageFile(argv[1]);assert(m.valid);auto p=buildNeuralExecutionPlan(m,200,150,3);if(!p.valid){std::cerr<<p.failureReason<<"\n";return 3;}assert(p.tiles.paddedWidth==200&&p.tiles.paddedHeight==152);assert(p.tileCount==12);assert(p.tiles.halo==40);assert((p.tiles.tileInputWidth()%8u)==0u);assert(p.kernelDispatchesPerTile==92);assert(p.persistentArenaBytesPerSlot==p.activationBytesPerSlot*3);auto first=neuralTileAt(p.tiles,0);assert(first.inputX==0&&first.inputY==0&&first.validX==0&&first.validY==0);assert(first.inputWidth==104&&first.inputHeight==104);auto second=neuralTileAt(p.tiles,1);assert(second.inputX==24&&second.validX==40&&second.inputWidth==144);bool copy=false,film=false,gate=false,write=false,up=false;for(auto&o:p.ops){copy|=o.primitive==NeuralPrimitive::Copy;film|=o.primitive==NeuralPrimitive::Film;gate|=o.primitive==NeuralPrimitive::SimpleGate;write|=o.primitive==NeuralPrimitive::Writeback;up|=o.upsample2x;if(o.primitive==NeuralPrimitive::Conv||o.primitive==NeuralPrimitive::Film||o.primitive==NeuralPrimitive::SimpleGate||o.primitive==NeuralPrimitive::ScaledAdd||o.primitive==NeuralPrimitive::Add)assert(o.src0!=o.dst);}assert(copy&&film&&gate&&write&&up);std::cout<<"NeuralExecutionPlanTest PASS ops="<<p.ops.size()<<" dispatches="<<p.kernelDispatchesPerTile<<"\n";}
